import requests

def test_post_driver_revocation_with_valid_internal_secret():
    base_url = "http://localhost:8000"
    url = f"{base_url}/api/v1/internal/driver-revocation"
    headers = {
        "Authorization": "Bearer eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    }

    try:
        response = requests.post(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code in (200, 202), f"Expected status code 200 or 202, got {response.status_code}"


test_post_driver_revocation_with_valid_internal_secret()
